/**
 * Short prestige burst on the creature modal sprite (~1s).
 */

import { PRESTIGE_STAR_IMG_URL } from '../../formatters.ts';

/** Total burst duration — must cover longest CSS animation (particles ~1.1s). */
export const PRESTIGE_BURST_MS = 1200;

const PARTICLE_COUNT = 6;
const BURST_SELECTOR = '#creatureModal.show .creature-modal-sprite-wrap';
const CREATURE_MODAL_ID = 'creatureModal';
const MODAL_BURST_CLASS = 'prestige-burst-modal-active';
const WAIT_FRAMES_MAX = 24;

export function prefersReducedMotion(): boolean {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

/** Remove burst overlay nodes and active class from a sprite wrap. */
export function cleanupPrestigeBurst(wrap: Element | null): void {
    if (!wrap) return;
    wrap.classList.remove('prestige-burst-active');
    wrap.querySelectorAll('.prestige-burst-ring, .prestige-burst-badge, .prestige-burst-particles').forEach((el) => el.remove());
}

function findBurstWrap(): Element | null {
    if (typeof document === 'undefined') return null;
    return document.querySelector(BURST_SELECTOR);
}

function setModalBurstActive(active: boolean): void {
    if (typeof document === 'undefined') return;
    document.getElementById(CREATURE_MODAL_ID)?.classList.toggle(MODAL_BURST_CLASS, active);
}

function waitForNextFrame(): Promise<void> {
    return new Promise((resolve) => {
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => resolve());
        } else {
            resolve();
        }
    });
}

/** Caller must await showCreatureModal() first — short safety poll if paint lags. */
async function waitForBurstWrap(maxFrames = WAIT_FRAMES_MAX): Promise<Element | null> {
    for (let i = 0; i < maxFrames; i++) {
        const wrap = findBurstWrap();
        if (wrap) return wrap;
        await waitForNextFrame();
    }
    return null;
}

function injectBurstOverlay(wrap: Element, prestige: number): void {
    cleanupPrestigeBurst(wrap);
    wrap.classList.add('prestige-burst-active');

    const ring = document.createElement('div');
    ring.className = 'prestige-burst-ring';
    ring.setAttribute('aria-hidden', 'true');
    wrap.appendChild(ring);

    const particlesHost = document.createElement('div');
    particlesHost.className = 'prestige-burst-particles';
    particlesHost.setAttribute('aria-hidden', 'true');
    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const particle = document.createElement('span');
        particle.className = 'prestige-burst-particle';
        particlesHost.appendChild(particle);
    }
    wrap.appendChild(particlesHost);

    const badge = document.createElement('div');
    badge.className = 'prestige-burst-badge';
    badge.setAttribute('aria-hidden', 'true');
    badge.innerHTML =
        `<img src="${PRESTIGE_STAR_IMG_URL}" class="prestige-burst-badge-star" alt="" aria-hidden="true">` +
        `<span class="prestige-burst-badge-label">${prestige}</span>`;
    wrap.appendChild(badge);
}

export async function playPrestigeBurst(opts: {
    prestige: number;
    reducedMotion?: boolean;
}): Promise<void> {
    const skipAnim = opts.reducedMotion === true || prefersReducedMotion();
    if (skipAnim) {
        return;
    }

    setModalBurstActive(true);
    try {
        const wrap = await waitForBurstWrap();
        if (!wrap) {
            return;
        }

        const prestige = Math.max(1, Math.floor(Number(opts.prestige) || 0));
        injectBurstOverlay(wrap, prestige);
        // Let injected nodes paint before animations start (avoids first-frame clip).
        await waitForNextFrame();
        await waitForNextFrame();

        await new Promise<void>((resolve) => {
            window.setTimeout(() => {
                cleanupPrestigeBurst(wrap);
                resolve();
            }, PRESTIGE_BURST_MS);
        });
    } finally {
        setModalBurstActive(false);
    }
}
